// components/ChatBox.js
import React, { useState } from "react";

const ChatBox = () => {
    const [open, setOpen] = useState(false);
    const [messages, setMessages] = useState([
        { from: "ai", text: "Hi! I'm BlackTide AI. Ask me anything~" },
    ]);
    const [input, setInput] = useState("");

    const handleSend = () => {
        if (!input.trim()) return;
        setMessages([
            ...messages,
            { from: "user", text: input },
            { from: "ai", text: "Sorry, I'm just a placeholder for now." },
        ]);
        setInput("");
    };

    return (
        <div className="fixed bottom-4 left-4 z-50 text-sm">
            {!open ? (
                <button
                    onClick={() => setOpen(true)}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-full shadow hover:bg-indigo-700"
                >
                    💬 Chat
                </button>
            ) : (
                <div className="bg-gray-900 text-white w-72 rounded-lg shadow-xl overflow-hidden">
                    <div className="bg-gray-800 px-4 py-2 font-bold flex justify-between">
                        <span>BlackTide AI</span>
                        <button
                            onClick={() => setOpen(false)}
                            className="text-sm"
                        >
                            ✖
                        </button>
                    </div>
                    <div className="h-48 overflow-y-auto p-3 space-y-2">
                        {messages.map((msg, idx) => (
                            <div
                                key={idx}
                                className={`text-left ${
                                    msg.from === "ai"
                                        ? "text-indigo-300"
                                        : "text-white"
                                }`}
                            >
                                <span className="block">{msg.text}</span>
                            </div>
                        ))}
                    </div>
                    <div className="flex border-t border-gray-700">
                        <input
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            className="flex-1 bg-gray-800 px-3 py-2 text-white outline-none"
                            placeholder="Type here..."
                        />
                        <button
                            onClick={handleSend}
                            className="bg-indigo-600 px-3"
                        >
                            ➤
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ChatBox;
