import React from "react";
import Typewriter from "typewriter-effect";

const Title = () => {
    return (
        <div className="text-center mt-32 z-10 relative">
            <h1 className="text-4xl md:text-6xl font-bold mb-4 drop-shadow-lg">
                <Typewriter
                    options={{
                        strings: [
                            "ACG × 技术 × 创意系统构建者",
                            "Sakura Dev | 梦想架构师",
                            "个性 × 自动化 × 沉浸体验",
                        ],
                        autoStart: true,
                        loop: true,
                    }}
                />
            </h1>
        </div>
    );
};

export default Title;
